import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CTABLES-Missing-Values-for-Cell_002dDefining-Variables.md","filePath":"manual-zh/CTABLES-Missing-Values-for-Cell_002dDefining-Variables.md","lastUpdated":1785684581000}'),h={name:"manual-zh/CTABLES-Missing-Values-for-Cell_002dDefining-Variables.md"};function i(n,t,o,l,s,S){return r(),e("div",null,[...t[0]||(t[0]=[a(`<h4 id="_15-7-9-1-单元格定义变量的缺失值" tabindex="-1">15.7.9.1 单元格定义变量的缺失值 <a class="header-anchor" href="#_15-7-9-1-单元格定义变量的缺失值" aria-label="Permalink to &quot;15.7.9.1 单元格定义变量的缺失值&quot;">​</a></h4><p>对于将表划分为单元格的变量，<a href="./CTABLES-Per_002dVariable-Category-Options">CTABLES Per-Variable Category Options</a> 中描述的各变量类别选项决定了哪些数据被分析。如果此类变量的任一类别会排除某个个案，则该个案不被纳入。</p><p>作为示例，考虑以下完全人为构造的数据集，其中 ‘x’ 和 ‘y’ 是缺失值为 9 的分类变量，‘z’ 是标度变量：</p><table tabindex="0"><thead><tr><th>x</th><th>y</th><th>z</th></tr></thead><tbody><tr><td>1</td><td>1</td><td>1</td></tr><tr><td>1</td><td>2</td><td>10</td></tr><tr><td>1</td><td>9</td><td>100</td></tr><tr><td>2</td><td>1</td><td>1000</td></tr><tr><td>2</td><td>2</td><td>10000</td></tr><tr><td>2</td><td>9</td><td>100000</td></tr><tr><td>9</td><td>1</td><td>1000000</td></tr><tr><td>9</td><td>2</td><td>10000000</td></tr><tr><td>9</td><td>9</td><td>100000000</td></tr></tbody></table><p>使用 ‘x’ 和 ‘y’ 定义单元格，并对 ‘z’ 进行汇总，默认情况下 PSPP 会省略所有 ‘x’ 或 ‘y’（或二者）缺失的个案：</p><pre><code>CTABLES /TABLE x &gt; y &gt; z [SUM].
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th></th><th></th><th>Sum</th></tr></thead><tbody><tr><td>x</td><td>1</td><td>y</td><td>1</td><td>z</td><td>1</td></tr><tr><td>2</td><td>z</td><td>10</td><td></td><td></td><td></td></tr><tr><td>2</td><td>y</td><td>1</td><td>z</td><td>1000</td><td></td></tr><tr><td>2</td><td>z</td><td>10000</td><td></td><td></td><td></td></tr></tbody></table><p>然而，如果我们添加 <code>CATEGORIES</code> 说明以包含 ‘y’ 或 ‘x’ 和 ‘y’ 的缺失值，输出表就会包含它们，如下所示：</p><pre><code>CTABLES /TABLE x &gt; y &gt; z [SUM] /CATEGORIES VARIABLES=y MISSING=INCLUDE.
CTABLES /TABLE x &gt; y &gt; z [SUM] /CATEGORIES VARIABLES=x y MISSING=INCLUDE.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th></th><th></th><th>Sum</th></tr></thead><tbody><tr><td>x</td><td>1</td><td>y</td><td>1</td><td>z</td><td>1</td></tr><tr><td>2</td><td>z</td><td>10</td><td></td><td></td><td></td></tr><tr><td>9</td><td>z</td><td>100</td><td></td><td></td><td></td></tr><tr><td>2</td><td>y</td><td>1</td><td>z</td><td>1000</td><td></td></tr><tr><td>2</td><td>z</td><td>10000</td><td></td><td></td><td></td></tr><tr><td>9</td><td>z</td><td>100000</td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>Sum</td></tr><tr><td>x</td><td>1</td><td>y</td><td>1</td><td>z</td><td>1</td></tr><tr><td>2</td><td>z</td><td>10</td><td></td><td></td><td></td></tr><tr><td>9</td><td>z</td><td>100</td><td></td><td></td><td></td></tr><tr><td>2</td><td>y</td><td>1</td><td>z</td><td>1000</td><td></td></tr><tr><td>2</td><td>z</td><td>10000</td><td></td><td></td><td></td></tr><tr><td>9</td><td>z</td><td>100000</td><td></td><td></td><td></td></tr><tr><td>9</td><td>y</td><td>1</td><td>z</td><td>1000000</td><td></td></tr><tr><td>2</td><td>z</td><td>10000000</td><td></td><td></td><td></td></tr><tr><td>9</td><td>z</td><td>100000000</td><td></td><td></td><td></td></tr></tbody></table>`,10)])])}const p=d(h,[["render",i]]);export{_ as __pageData,p as default};
